	err := withWatchCursorLock(cursorPath, func() error {
		cursor = loadWatchCursor(cursorPath)
		changed := fingerprint != cursor.LastFingerprint || cursor.LastRefreshAt.IsZero()
		if changed {
			cursor.LastFingerprint = fingerprint
