	// small fraction; the exact schedule is 5m/10m/20m/30m/30m over 100 minutes.
	if refreshes >= ticks {
		t.Fatalf("failed delta must not consolidate every tick: refreshes=%d over %d ticks\n%s", refreshes, ticks, out.String())
